// Conjugation drills for language courses: generate a word's forms from its dictionary form
// and class, build rounds of prompts from the words and forms the learner has unlocked, check
// typed answers (same leniencies as vocabulary recall) and keep per-form accuracy.
//
// Japanese: every form is generated from `term` + `reading` by the standard rules for the
// word's class, with the rule-based exceptions 行く (いって), ある (ない) and いい (よ-). Verbs
// whose forms don't follow the rules (くださる, 問う…) are refused, never guessed.
// German: weak verbs and adjectives are generated by rule; strong, mixed and modal verbs carry
// their irregular parts in `forms`. Anything the rules can't settle (a verb that might have a
// prefix, an e→i imperative) is refused unless the data says.
//
// Data format: docs/COURSE_FORMAT.md, "Conjugation drills". Field lists: courseConjugation.ts.

import type { ConjTally, Course, Progress, VocabItem } from "./types";
import {
  DE_ADJ_FORMS,
  DE_VERB_FORMS,
  JA_ADJ_FORMS,
  JA_VERB_FORMS,
  type ConjugationFormSetting,
  type DeForms,
} from "./courseConjugation";
import { checkRecall, checkRecallJa, shuffled, unlockedItems, type Verdict } from "./vocab";
import { hasKanji, isKanaOnly, isKanji, stripRuby } from "./kana";
import { today } from "./srs";

// ---------------------------------------------------------------------------------------------
// Results

export interface Generated {
  /** Accepted answers, the usual one first. */
  answers: string[];
  /** Japanese: kana readings, parallel to answers. */
  readings?: string[];
  /** One line: the rule that makes this form. */
  rule: string;
}

const JA_VERB_CLASSES = ["godan", "ichidan", "suru", "kuru"];
const JA_ADJ_CLASSES = ["i-adj", "ii-adj", "na-adj"];

// ---------------------------------------------------------------------------------------------
// Japanese

/** Godan endings and their あ, い, う, え, お rows. */
const ROWS: Record<string, string> = {
  う: "わいうえお",
  く: "かきくけこ",
  ぐ: "がぎぐげご",
  す: "さしすせそ",
  つ: "たちつてと",
  ぬ: "なにぬねの",
  ぶ: "ばびぶべぼ",
  む: "まみむめも",
  る: "らりるれろ",
};
/** Kana of the い and え rows: an ichidan verb has one of these before its る. */
const I_E_ROW = new Set([..."いきぎしじちぢにひびぴみりえけげせぜてでねへべぺめれ"]);

/** Godan verbs whose polite, imperative or て forms break the rules: not generated. */
const JA_UNSUPPORTED = ["くださる", "なさる", "いらっしゃる", "おっしゃる", "ござる"];
const JA_UNSUPPORTED_TERMS = ["問う", "請う", "乞う"];

const TE: Record<string, [string, string]> = {
  う: ["って", "った"],
  つ: ["って", "った"],
  る: ["って", "った"],
  む: ["んで", "んだ"],
  ぶ: ["んで", "んだ"],
  ぬ: ["んで", "んだ"],
  く: ["いて", "いた"],
  ぐ: ["いで", "いだ"],
  す: ["して", "した"],
};
const TE_RULE: Record<string, string> = {
  う: "う, つ, る → って",
  つ: "う, つ, る → って",
  る: "う, つ, る → って",
  む: "む, ぶ, ぬ → んで",
  ぶ: "む, ぶ, ぬ → んで",
  ぬ: "む, ぶ, ぬ → んで",
  く: "く → いて",
  ぐ: "ぐ → いで",
  す: "す → して",
};

interface JaWord {
  cls: string;
  /** Written and kana dictionary forms without the part that changes. */
  wStem: string;
  rStem: string;
  /** The changing ending in kana (く, る, する, くる, い, いい, or nothing). */
  end: string;
  /** 来る written with its kanji. */
  kanjiKuru?: boolean;
  /** 良い read いい: the written stem already holds the よ. */
  yoKanji?: boolean;
  term: string;
  reading: string;
}

/** Why a Japanese word can't be conjugated, or undefined when it can. */
export function jaWordProblem(item: VocabItem): string | undefined {
  const w = jaWord(item);
  return typeof w === "string" ? w : undefined;
}

function jaWord(item: VocabItem): JaWord | string {
  const cls = item.conj ?? "";
  const term = stripRuby(item.term).trim();
  if (hasKanji(term) && !item.reading) return `"${term}" has kanji, so it needs a kana "reading" to conjugate`;
  const reading = (item.reading ?? term).trim();
  if (!isKanaOnly(reading)) return `the reading "${reading}" must be kana only`;
  const ends = (s: string, e: string) => s.endsWith(e) && s.length >= e.length;
  const split = (e: string, written = e): JaWord | string => {
    if (!ends(reading, e)) return `a ${cls} word's dictionary form ends in ${e} (the reading is "${reading}")`;
    if (!ends(term, written)) return `"${term}" doesn't end in ${written} like its reading "${reading}"`;
    return { cls, term, reading, end: e, rStem: reading.slice(0, -e.length || undefined), wStem: term.slice(0, term.length - written.length) };
  };
  switch (cls) {
    case "godan": {
      const last = reading.slice(-1);
      if (!ROWS[last]) return `godan verbs end in う, く, ぐ, す, つ, ぬ, ぶ, む or る (the reading is "${reading}")`;
      if (JA_UNSUPPORTED.some((v) => reading.endsWith(v)) || JA_UNSUPPORTED_TERMS.some((v) => term.endsWith(v)))
        return `"${term}" has irregular forms (honorific ます/imperative, or う-verb て form) that aren't generated; leave out "conj"`;
      return split(last);
    }
    case "ichidan": {
      if (!ends(reading, "る") || reading.length < 2 || !I_E_ROW.has(reading.slice(-2, -1)))
        return `ichidan verbs end in る with an い- or え-row kana before it (the reading is "${reading}")`;
      return split("る");
    }
    case "suru":
      return split("する");
    case "kuru": {
      if (!ends(reading, "くる")) return `来る verbs end in くる (the reading is "${reading}")`;
      if (ends(term, "来る")) return { cls, term, reading, end: "くる", rStem: reading.slice(0, -2), wStem: term.slice(0, -2), kanjiKuru: true };
      return split("くる");
    }
    case "i-adj": {
      if (reading === "いい") return jaWord({ ...item, conj: "ii-adj" });
      return split("い");
    }
    case "ii-adj": {
      if (!ends(reading, "いい")) return `"ii-adj" is for いい and words ending in it (かっこいい); the reading is "${reading}"`;
      // いい → よ-: 良い / かっこいい / いい
      const cls2 = "ii-adj";
      if (ends(term, "いい")) return { cls: cls2, term, reading, end: "いい", rStem: reading.slice(0, -2), wStem: term.slice(0, -2) };
      // 良い read いい: the kanji stands for よ (良くない).
      if (ends(term, "い") && isKanji(term.slice(-2, -1)))
        return { cls: cls2, term, reading, end: "いい", rStem: reading.slice(0, -2), wStem: term.slice(0, -1), yoKanji: true };
      return `"${term}" should end in いい or 良い`;
    }
    case "na-adj": {
      if (/[なだ]$/.test(term) && term.length > 1) return `write a な-adjective without な or だ ("${term.slice(0, -1)}")`;
      return { cls, term, reading, end: "", rStem: reading, wStem: term };
    }
    default:
      return `"${cls}" isn't a Japanese conjugation class (${[...JA_VERB_CLASSES, ...JA_ADJ_CLASSES].join(", ")})`;
  }
}

/** Kana endings (alternatives, usual first) and the rule for one form of one word. */
function jaEndings(w: JaWord, form: string): { ends: string[]; rule: string; whole?: boolean } | undefined {
  const { cls, reading } = w;
  if (cls === "godan") {
    const last = w.end;
    const row = ROWS[last];
    const [a, i, , e, o] = [...row];
    const iku = last === "く" && reading.endsWith("いく") && (w.term.endsWith("行く") || w.term.endsWith("いく"));
    const aru = reading === "ある";
    const g = "Group 1 (う-verb)";
    const toRow = (k: string, rowName: string, add: string) =>
      `${g}: ${last} → ${k} (the ${rowName}-row), then ${add}${last === "う" && rowName === "あ" ? " (う becomes わ, not あ)" : ""}`;
    switch (form) {
      case "polite":
        return { ends: [i + "ます"], rule: toRow(i, "い", "ます") };
      case "polite-negative":
        return { ends: [i + "ません"], rule: toRow(i, "い", "ません") };
      case "polite-past":
        return { ends: [i + "ました"], rule: toRow(i, "い", "ました") };
      case "polite-past-negative":
        return { ends: [i + "ませんでした"], rule: toRow(i, "い", "ませんでした") };
      case "negative":
        if (aru) return { ends: ["ない"], rule: "ある is irregular: its negative is ない (not あらない)", whole: true };
        return { ends: [a + "ない"], rule: toRow(a, "あ", "ない") };
      case "past-negative":
        if (aru) return { ends: ["なかった"], rule: "ある is irregular: its negative is ない, so the past negative is なかった", whole: true };
        return { ends: [a + "なかった"], rule: toRow(a, "あ", "なかった") };
      case "te":
      case "past": {
        const k = form === "te" ? 0 : 1;
        if (iku) return { ends: [["って", "った"][k]], rule: `行く is the exception: ${form === "te" ? "いって" : "いった"} (not ${form === "te" ? "いいて" : "いいた"})` };
        const t = TE[last];
        return { ends: [t[k]], rule: `${g} ${form === "te" ? "て form" : "past"}: ${k ? TE_RULE[last].replace(/て/g, "た").replace(/で/g, "だ") : TE_RULE[last]}` };
      }
      case "volitional":
        return { ends: [o + "う"], rule: toRow(o, "お", "う") };
      case "potential":
        if (aru) return undefined;
        return { ends: [e + "る"], rule: toRow(e, "え", "る") };
      case "conditional":
        return { ends: [e + "ば"], rule: toRow(e, "え", "ば") };
      case "passive":
        if (aru) return undefined;
        return { ends: [a + "れる"], rule: toRow(a, "あ", "れる") };
      case "causative":
        if (aru) return undefined;
        return { ends: [a + "せる"], rule: toRow(a, "あ", "せる") };
      case "imperative":
        if (aru) return undefined;
        return { ends: [e], rule: `${g}: ${last} → ${e} (the え-row)` };
    }
    return undefined;
  }
  if (cls === "ichidan") {
    const add: Record<string, string> = {
      polite: "ます",
      "polite-negative": "ません",
      "polite-past": "ました",
      "polite-past-negative": "ませんでした",
      negative: "ない",
      past: "た",
      "past-negative": "なかった",
      te: "て",
      volitional: "よう",
      potential: "られる",
      conditional: "れば",
      passive: "られる",
      causative: "させる",
      imperative: "ろ",
    };
    if (!add[form]) return undefined;
    if (form === "imperative" && reading === "くれる") return undefined; // くれ
    return { ends: [add[form]], rule: `Group 2 (る-verb): drop る, add ${add[form]}` };
  }
  if (cls === "suru") {
    const add: Record<string, string[]> = {
      polite: ["します"],
      "polite-negative": ["しません"],
      "polite-past": ["しました"],
      "polite-past-negative": ["しませんでした"],
      negative: ["しない"],
      past: ["した"],
      "past-negative": ["しなかった"],
      te: ["して"],
      volitional: ["しよう"],
      potential: ["できる"],
      conditional: ["すれば"],
      passive: ["される"],
      causative: ["させる"],
      imperative: ["しろ", "せよ"],
    };
    if (!add[form]) return undefined;
    return {
      ends: add[form],
      rule: form === "potential" ? "Group 3: the potential of する is できる" : `Group 3 (irregular): する → ${add[form][0]}`,
    };
  }
  if (cls === "kuru") {
    const add: Record<string, string> = {
      polite: "きます",
      "polite-negative": "きません",
      "polite-past": "きました",
      "polite-past-negative": "きませんでした",
      negative: "こない",
      past: "きた",
      "past-negative": "こなかった",
      te: "きて",
      volitional: "こよう",
      potential: "こられる",
      conditional: "くれば",
      passive: "こられる",
      causative: "こさせる",
      imperative: "こい",
    };
    if (!add[form]) return undefined;
    return { ends: [add[form]], rule: `Group 3 (irregular): 来る (くる) → ${add[form]}` };
  }
  if (cls === "i-adj" || cls === "ii-adj") {
    const add: Record<string, string> = {
      "adj-negative": "くない",
      "adj-past": "かった",
      "adj-past-negative": "くなかった",
      "adj-te": "くて",
      adverb: "く",
    };
    if (!add[form]) return undefined;
    if (cls === "ii-adj")
      return { ends: ["よ" + add[form]], rule: `いい is irregular: it conjugates from よい, so drop い and add ${add[form]} (よ${add[form]})` };
    return { ends: [add[form]], rule: `い-adjective: drop the last い, add ${add[form]}` };
  }
  if (cls === "na-adj") {
    const add: Record<string, string[]> = {
      "adj-negative": ["じゃない", "ではない"],
      "adj-past": ["だった"],
      "adj-past-negative": ["じゃなかった", "ではなかった"],
      "adj-te": ["で"],
      adverb: ["に"],
    };
    if (!add[form]) return undefined;
    return { ends: add[form], rule: `な-adjective: add ${add[form].join(" (or ")}${add[form].length > 1 ? ")" : ""}` };
  }
  return undefined;
}

/** One form of a Japanese verb or adjective: written forms and kana readings. */
export function jaForm(item: VocabItem, form: string): Generated | undefined {
  const w = jaWord(item);
  if (typeof w === "string") return undefined;
  const e = jaEndings(w, form);
  if (!e) return undefined;
  const readings = e.ends.map((x) => (e.whole ? x : w.rStem + x));
  const answers = e.ends.map((x) => {
    if (e.whole) return x;
    // 来る keeps its kanji: こない → 来ない, きます → 来ます.
    if (w.kanjiKuru) return w.wStem + "来" + x.slice(1);
    if (w.yoKanji) return w.wStem + x.slice(1);
    return w.wStem + x;
  });
  return { answers, readings, rule: e.rule };
}

/** Warnings for a Japanese word to look at again (not errors): classes that are easy to mix up. */
export function jaWordWarnings(item: VocabItem): string[] {
  const out: string[] = [];
  const reading = (item.reading ?? stripRuby(item.term)).trim();
  const term = stripRuby(item.term).trim();
  if (item.conj === "godan" && reading.endsWith("る") && I_E_ROW.has(reading.slice(-2, -1)))
    out.push(`godan verb ending in ${reading.slice(-2)} looks like an ichidan verb; confirm it's godan (帰る, 入る, 知る, 切る, 走る are godan)`);
  const homophones: Record<string, string> = {
    きる: "切る (to cut) is godan, 着る (to wear) is ichidan",
    かえる: "帰る (to go home) is godan, 変える (to change) is ichidan",
    いる: "要る (to need) is godan, いる/居る (to be) is ichidan",
    へる: "減る (to decrease) is godan, 経る (to pass) is ichidan",
    ねる: "練る (to knead) is godan, 寝る (to sleep) is ichidan",
    しる: "知る (to know) is godan",
    はいる: "入る (to enter) is godan",
  };
  if ((item.conj === "ichidan" || item.conj === "godan") && homophones[reading]) out.push(`${reading}: ${homophones[reading]}; check the class matches the meaning`);
  if (item.conj === "godan" && term.endsWith("来る")) out.push(`"${term}" ends in 来る: did you mean "kuru"?`);
  if (item.conj === "godan" && reading.endsWith("する")) out.push(`"${term}" ends in する: did you mean "suru"?`);
  if (item.conj === "suru" && /^[㐀-䶿一-鿿]する$/.test(term))
    out.push(`"${term}" is a one-kanji する verb; some (愛する, 訳する) conjugate like godan す-verbs in places (愛さない): check its forms`);
  if (item.conj === "i-adj" && ["きれい", "きらい", "ゆうめい", "ていねい", "しつれい", "とくい"].includes(reading))
    out.push(`${reading} ends in い but is a な-adjective; use "na-adj"`);
  if (item.conj === "i-adj" && reading.endsWith("いい") && reading !== "いい")
    out.push(`"${term}" ends in いい: if it's built on いい "good" (かっこいい), use "ii-adj" (かっこよくない); かわいい is regular`);
  return out;
}

// ---------------------------------------------------------------------------------------------
// German

export type DePerson = "ich" | "du" | "er" | "wir" | "ihr" | "sie";
export const DE_PERSONS: DePerson[] = ["ich", "du", "er", "wir", "ihr", "sie"];
export type DeImperative = "du" | "ihr" | "Sie";
export const DE_IMPERATIVES: DeImperative[] = ["du", "ihr", "Sie"];
const PERSON_LABEL: Record<string, string> = { ich: "ich", du: "du", er: "er/sie/es", wir: "wir", ihr: "ihr", sie: "sie/Sie", Sie: "Sie" };
const PRONOUNS: Record<DePerson, string[]> = { ich: ["ich"], du: ["du"], er: ["er", "sie", "es"], wir: ["wir"], ihr: ["ihr"], sie: ["sie", "Sie"] };

const INSEPARABLE = ["be", "emp", "ent", "er", "ge", "miss", "ver", "zer"];
const SEPARABLE = [
  "ab", "an", "auf", "aus", "bei", "dabei", "durch", "ein", "fern", "fest", "heim", "her", "herein", "hin", "hinaus", "los", "mit", "nach",
  "statt", "teil", "über", "um", "unter", "vor", "vorbei", "weg", "weiter", "wieder", "zu", "zurück", "zusammen",
];
/** Weak verbs that take sein in the Perfekt: they need an explicit `forms.perfect`. */
const WEAK_SEIN = ["reisen", "wandern", "joggen", "landen", "folgen", "begegnen", "klettern", "segeln", "rudern", "surfen", "passieren", "bummeln", "eilen", "stürzen", "rennen", "starten", "aufwachen", "umziehen", "einschlafen"];
const NON_INFLECTING = ["lila", "rosa", "prima", "super", "klasse", "beige", "cool", "extra"];

/** The prefix a verb seems to start with (it may or may not be one: beten, antworten). */
function prefixOf(term: string): { prefix: string; separable: boolean } | undefined {
  const all = [...INSEPARABLE.map((p) => ({ prefix: p, separable: false })), ...SEPARABLE.map((p) => ({ prefix: p, separable: true }))].sort(
    (a, b) => b.prefix.length - a.prefix.length,
  );
  return all.find((p) => term.startsWith(p.prefix) && term.length - p.prefix.length >= 4);
}

const VOWEL = /[aeiouäöüy]/;
/** Stems in -t/-d, or consonant + m/n (atmen, öffnen, rechnen), insert -e- before -st/-t. */
export function needsE(stem: string): boolean {
  if (/[td]$/.test(stem)) return true;
  if (/[mn]$/.test(stem)) {
    const b = stem.slice(-2, -1);
    if (!b || VOWEL.test(b) || b === stem.slice(-1) || b === "l" || b === "r") return false;
    if (b === "h") return stem.slice(-3, -2) === "c"; // rechnen (ch) vs wohnen (lengthening h)
    return true;
  }
  return false;
}
const sibilant = (stem: string) => /[sßzx]$/.test(stem);

interface DeVerb {
  term: string;
  cls: string;
  base: string;
  sep?: string;
  stem: string;
  eln: boolean;
  ern: boolean;
  f: DeForms;
}

/** Why a German word can't be conjugated, or undefined when it can. */
export function deWordProblem(item: VocabItem): string | undefined {
  if (item.conj === "adj") {
    const a = deAdj(item);
    return typeof a === "string" ? a : undefined;
  }
  const v = deVerb(item);
  return typeof v === "string" ? v : undefined;
}

function deVerb(item: VocabItem): DeVerb | string {
  const term = item.term.trim();
  const cls = item.conj ?? "";
  const f = item.forms ?? {};
  if (!["weak", "strong", "mixed", "modal"].includes(cls)) return `"${cls}" isn't a German verb class (weak, strong, mixed, modal) or "adj"`;
  if (!/^[a-zäöüß]+$/.test(term)) return `"${term}" must be a one-word infinitive in lower case (reflexive and multi-word verbs aren't drilled)`;
  if (!/n$/.test(term)) return `"${term}" doesn't look like an infinitive (it should end in -n or -en)`;
  const sep = f.sep;
  if (sep && !term.startsWith(sep)) return `forms.sep "${sep}" isn't at the start of "${term}"`;
  const base = sep ? term.slice(sep.length) : term;
  for (const k of ["present1", "present2", "present3", "present1pl", "present2pl", "preterite", "imperative", "imperativeSie", "subjunctive"] as const)
    if (sep && f[k] && !f[k]!.endsWith(` ${sep}`)) return `forms.${k} "${f[k]}" should end with the separable prefix (" ${sep}")`;
  if (f.perfect) {
    if (!/^(hat|ist) \S+$/.test(f.perfect)) return `forms.perfect "${f.perfect}" should be "hat …" or "ist …" with the participle (er/sie/es form)`;
    if (sep && !f.perfect.split(" ")[1].startsWith(sep)) return `forms.perfect "${f.perfect}": the participle should start with "${sep}"`;
  }
  const pre = prefixOf(term);
  if (pre && !sep) {
    if (!f.perfect) return `"${term}" may start with the prefix ${pre.prefix}-: give forms.perfect (and forms.sep if it's separable) so its forms aren't guessed`;
    if (pre.separable && f.perfect.split(" ")[1].startsWith(pre.prefix + "ge")) return `"${term}" looks separable (${f.perfect}): add forms.sep "${pre.prefix}"`;
  }
  const missing = (keys: (keyof DeForms)[]) => keys.filter((k) => !f[k]);
  const need =
    cls === "strong" ? missing(["present2", "present3", "preterite", "perfect"]) : cls === "mixed" ? missing(["preterite", "perfect"]) : cls === "modal" ? missing(["present1", "preterite", "perfect"]) : [];
  if (need.length) return `${cls} verbs need ${need.map((k) => `forms.${k}`).join(", ")}`;
  if (cls === "weak" && !f.perfect && WEAK_SEIN.includes(term)) return `"${term}" takes sein in the Perfekt: give forms.perfect ("ist …")`;
  if (!!f.present2 !== !!f.present3 && cls !== "modal") return `give both forms.present2 and forms.present3 (du and er/sie/es) for a stem change`;
  if (f.subjunctive && !/e$/.test(f.subjunctive.replace(sep ? ` ${sep}` : "", ""))) return `forms.subjunctive "${f.subjunctive}" should be the er/sie/es form ending in -e (wäre, hätte, würde)`;
  const eln = /[^aeiouäöü]eln$/.test(base);
  const ern = /[^aeiouäöü]ern$/.test(base) && !/rnen$/.test(base);
  const stem = eln || ern ? base.slice(0, -1) : base.endsWith("en") ? base.slice(0, -2) : base.slice(0, -1);
  if (!stem) return `can't find the stem of "${term}"`;
  return { term, cls, base, sep, stem, eln, ern, f };
}

const withSep = (v: DeVerb, s: string) => (v.sep ? `${s} ${v.sep}` : s);
const noSep = (v: DeVerb, s: string) => (v.sep && s.endsWith(` ${v.sep}`) ? s.slice(0, -v.sep.length - 1) : s);

function presentOf(v: DeVerb, p: DePerson): { form: string; given: boolean } {
  const { f, stem } = v;
  const e = needsE(stem);
  switch (p) {
    case "ich":
      if (f.present1) return { form: f.present1, given: true };
      return { form: withSep(v, v.eln ? stem.slice(0, -2) + "le" : stem + "e"), given: false };
    case "du":
      if (f.present2) return { form: f.present2, given: true };
      if (v.cls === "modal") {
        const p1 = noSep(v, f.present1!);
        return { form: withSep(v, p1 + (sibilant(p1) ? "t" : "st")), given: false };
      }
      return { form: withSep(v, stem + (sibilant(stem) ? "t" : e ? "est" : "st")), given: false };
    case "er":
      if (f.present3) return { form: f.present3, given: true };
      if (v.cls === "modal") return { form: f.present1!, given: true };
      return { form: withSep(v, stem + (e ? "et" : "t")), given: false };
    case "wir":
    case "sie":
      if (f.present1pl) return { form: f.present1pl, given: true };
      return { form: withSep(v, v.base), given: false };
    case "ihr":
      if (f.present2pl) return { form: f.present2pl, given: true };
      return { form: withSep(v, stem + (e ? "et" : "t")), given: false };
  }
}

function preteriteStem(v: DeVerb): { p: string; given: boolean } {
  if (v.f.preterite) return { p: noSep(v, v.f.preterite), given: true };
  return { p: v.stem + (needsE(v.stem) ? "ete" : "te"), given: false };
}

/** Person endings on a past stem: -e stems (machte, wurde, wäre) or bare strong stems (fuhr, las). */
function pastPersons(p: string, person: DePerson, contracted = false): string[] {
  if (p.endsWith("e")) {
    const s = p.slice(0, -1);
    const map: Record<DePerson, string[]> = {
      ich: [p],
      du: [s + "est", ...(contracted ? [s + "st"] : [])],
      er: [p],
      wir: [s + "en"],
      ihr: [s + "et", ...(contracted ? [s + "t"] : [])],
      sie: [s + "en"],
    };
    // schrie → schrien (no doubled e)
    if (s.endsWith("ie")) map.wir = map.sie = [s + "n"];
    return map[person];
  }
  const td = /[td]$/.test(p);
  const sib = /[sßzx]$/.test(p);
  switch (person) {
    case "ich":
    case "er":
      return [p];
    case "du":
      return td ? [p + "est"] : sib ? [p + "est", p + "t"] : [p + "st"];
    case "wir":
    case "sie":
      return [p + "en"];
    case "ihr":
      return td ? [p + "et"] : [p + "t"];
  }
}

const HABEN = { ich: "habe", du: "hast", er: "hat", wir: "haben", ihr: "habt", sie: "haben" };
const SEIN = { ich: "bin", du: "bist", er: "ist", wir: "sind", ihr: "seid", sie: "sind" };

/** e → i/ie stem change between the infinitive and er/sie/es (geben/gibt, lesen/liest). */
function eToI(stem: string, p3: string): boolean {
  const fold = (s: string) => s.replace(/ie/g, "I");
  const count = (s: string, c: string) => [...s].filter((x) => x === c).length;
  const a = fold(stem);
  const b = fold(p3);
  return count(b, "e") < count(a, "e") && count(b, "i") + count(b, "I") > count(a, "i") + count(a, "I");
}

function addPronouns(forms: string[], person: DePerson | undefined): string[] {
  if (!person) return forms;
  const prons = PRONOUNS[person];
  const out = [...forms];
  for (const f of forms)
    for (const pr of prons) {
      out.push(`${pr} ${f}`);
      out.push(`${pr[0].toUpperCase()}${pr.slice(1)} ${f}`);
    }
  return [...new Set(out)];
}

/** One German verb form for a person (imperatives: du, ihr or Sie). */
export function deVerbForm(item: VocabItem, form: string, person: string): Generated | undefined {
  const v = deVerb(item);
  if (typeof v === "string") return undefined;
  const { f, term } = v;
  const pers = person as DePerson;
  switch (form) {
    case "present": {
      if (!DE_PERSONS.includes(pers)) return undefined;
      const { form: x, given } = presentOf(v, pers);
      let rule: string;
      if (given && (pers === "ich" || pers === "wir" || pers === "ihr" || pers === "sie" || v.cls === "modal"))
        rule = `${term} is irregular in the present: ${PERSON_LABEL[pers]} ${x}`;
      else if (given) rule = `${term} changes its stem for du and er/sie/es: du ${f.present2}, er ${f.present3}`;
      else if (pers === "wir" || pers === "sie") rule = `wir and sie/Sie use the infinitive: ${x}`;
      else if (pers === "du" && sibilant(v.stem)) rule = `Stems ending in s, ß, z or x add only -t for du: du ${x}`;
      else if (pers !== "ich" && needsE(v.stem)) rule = `Stems ending in -t, -d or consonant + m/n add -e- before the ending: ${PERSON_LABEL[pers]} ${x}`;
      else if (pers === "ich" && v.eln) rule = `-eln verbs drop the e of -el for ich: ich ${x}`;
      else rule = `Present tense: stem ${v.stem}- + ${{ ich: "-e", du: "-st", er: "-t", ihr: "-t" }[pers as "ich"]}`;
      return { answers: addPronouns([x, ...(pers === "ich" && v.ern ? [withSep(v, v.stem.slice(0, -2) + "re")] : [])], pers), rule };
    }
    case "preterite": {
      if (!DE_PERSONS.includes(pers)) return undefined;
      const { p, given } = preteriteStem(v);
      const forms = pastPersons(p, pers).map((x) => withSep(v, x));
      const rule = given
        ? p.endsWith("te")
          ? `${term} has the Präteritum stem ${p.slice(0, -1)}- with weak endings: ${PERSON_LABEL[pers]} ${forms[0]}`
          : p.endsWith("e")
            ? `${term}: Präteritum ${p}, endings like a weak verb: ${PERSON_LABEL[pers]} ${forms[0]}`
            : `Strong verb: Präteritum stem ${p}-, endings: ich and er/sie/es none, du -st, wir/sie -en, ihr -t`
        : `Weak verb: stem + -${needsE(v.stem) ? "ete" : "te"} + ending: ${PERSON_LABEL[pers]} ${forms[0]}`;
      return { answers: addPronouns(forms, pers), rule };
    }
    case "perfect": {
      if (!DE_PERSONS.includes(pers)) return undefined;
      let aux: "hat" | "ist" = "hat";
      let part: string;
      let how: string;
      if (f.perfect) {
        [aux, part] = f.perfect.split(" ") as ["hat" | "ist", string];
        how = "";
      } else {
        // Weak, no prefix (checked in deVerb): ge- + stem + -t; -ieren verbs have no ge-.
        const core = v.base.endsWith("ieren") ? v.stem + "t" : "ge" + v.stem + (needsE(v.stem) ? "et" : "t");
        part = (v.sep ?? "") + core;
        how = v.base.endsWith("ieren") ? " (-ieren verbs take no ge-)" : v.sep ? ` (separable: ${v.sep} + ge- + stem + -t)` : " (weak: ge- + stem + -t)";
      }
      const x = `${(aux === "ist" ? SEIN : HABEN)[pers]} ${part}`;
      const rule = `Perfekt: ${aux === "ist" ? "sein" : "haben"} (${(aux === "ist" ? SEIN : HABEN)[pers]}) + the participle ${part}${how}`;
      return { answers: addPronouns([x], pers), rule };
    }
    case "imperative": {
      if (v.cls === "modal") return undefined;
      const imp = person as DeImperative;
      if (imp === "du") {
        if (f.imperative) return { answers: [f.imperative], rule: `du imperative of ${term}: ${f.imperative}!` };
        if (v.cls === "strong" && f.present3 && eToI(v.stem, noSep(v, f.present3))) return undefined; // gib, lies: must be given
        const s = v.stem;
        if (v.eln) return { answers: [withSep(v, s.slice(0, -2) + "le")], rule: `-eln verbs: du imperative ${withSep(v, s.slice(0, -2) + "le")}!` };
        if (v.ern) return { answers: [withSep(v, s + "e"), withSep(v, s.slice(0, -2) + "re")], rule: `-ern verbs: du imperative ${withSep(v, s + "e")}!` };
        if (needsE(s)) return { answers: [withSep(v, s + "e")], rule: `du imperative: the stem + -e after -t, -d or consonant + m/n: ${withSep(v, s + "e")}!` };
        return { answers: [withSep(v, s), withSep(v, s + "e")], rule: `du imperative: the stem without du (${withSep(v, s)}!); -e is optional` };
      }
      if (imp === "ihr") {
        const x = presentOf(v, "ihr").form;
        return { answers: [x], rule: `ihr imperative: the ihr form without ihr (${x}!)` };
      }
      if (imp === "Sie") {
        if (f.imperativeSie) return { answers: [f.imperativeSie], rule: `Sie imperative of ${term}: ${f.imperativeSie}!` };
        const x = v.sep ? `${v.base} Sie ${v.sep}` : `${v.base} Sie`;
        return { answers: [x], rule: `Sie imperative: infinitive + Sie (${x}!)` };
      }
      return undefined;
    }
    case "subjunctive": {
      if (!f.subjunctive || !DE_PERSONS.includes(pers)) return undefined;
      const p = noSep(v, f.subjunctive);
      // Strong-verb forms (wäre, käme) also have the short du/ihr forms (wärst, wärt); weak-looking ones (hätte, würde) don't.
      const forms = pastPersons(p, pers, !/[td]e$/.test(p)).map((x) => withSep(v, x));
      return { answers: addPronouns(forms, pers), rule: `Konjunktiv II of ${term}: ${f.subjunctive}, with the endings -e, -est, -e, -en, -et, -en` };
    }
  }
  return undefined;
}

// --- German adjectives ---------------------------------------------------------------------------

export type DeCase = "nom" | "acc" | "dat" | "gen";
export type DeGender = "m" | "f" | "n" | "pl";
export type DeArticle = "der" | "ein" | "none";
const CASE_INDEX: Record<DeCase, number> = { nom: 0, acc: 1, dat: 2, gen: 3 };
const GENDER_INDEX: Record<DeGender, number> = { m: 0, f: 1, n: 2, pl: 3 };
export const CASE_NAME: Record<DeCase, string> = { nom: "nominative", acc: "accusative", dat: "dative", gen: "genitive" };
const GENDER_NAME: Record<DeGender, string> = { m: "masculine", f: "feminine", n: "neuter", pl: "plural" };
const ARTICLES: Record<"der" | "ein", string[][]> = {
  der: [
    ["der", "die", "das", "die"],
    ["den", "die", "das", "die"],
    ["dem", "der", "dem", "den"],
    ["des", "der", "des", "der"],
  ],
  ein: [
    ["ein", "eine", "ein", "keine"],
    ["einen", "eine", "ein", "keine"],
    ["einem", "einer", "einem", "keinen"],
    ["eines", "einer", "eines", "keiner"],
  ],
};
const ENDINGS: Record<DeArticle, string[][]> = {
  der: [
    ["e", "e", "e", "en"],
    ["en", "e", "e", "en"],
    ["en", "en", "en", "en"],
    ["en", "en", "en", "en"],
  ],
  ein: [
    ["er", "e", "es", "en"],
    ["en", "e", "es", "en"],
    ["en", "en", "en", "en"],
    ["en", "en", "en", "en"],
  ],
  none: [
    ["er", "e", "es", "e"],
    ["en", "e", "es", "e"],
    ["em", "er", "em", "en"],
    ["en", "er", "en", "er"],
  ],
};

/** The adjective's attributive stem, or why it can't be drilled. */
function deAdj(item: VocabItem): string | { stem: string; rule?: string } {
  const term = item.term.trim();
  if (!/^[a-zäöüß]+$/.test(term)) return `"${term}" must be one lower-case word to drill adjective endings`;
  if (NON_INFLECTING.includes(term)) return `"${term}" takes no endings; leave out "conj"`;
  if (item.forms?.stem) return { stem: item.forms.stem, rule: `${term} → ${item.forms.stem}- before an ending` };
  if (term === "hoch" || term.endsWith("hoch")) return `"${term}" changes before an ending (hoh-): give forms.stem`;
  if (/[^aeiouäöü]el$/.test(term)) return { stem: term.slice(0, -2) + "l", rule: `-el adjectives drop the e: ${term} → ${term.slice(0, -2)}l-` };
  if (/(au|eu)er$/.test(term)) return { stem: term.slice(0, -2) + "r", rule: `-er after au/eu drops the e: ${term} → ${term.slice(0, -2)}r-` };
  if (term.endsWith("e")) return { stem: term.slice(0, -1) };
  return { stem: term };
}

/** A noun usable in adjective drills: "der Hund" + optional plural "die Hunde". */
export function deNoun(item: VocabItem): { gender: Exclude<DeGender, "pl">; noun: string; plural?: string } | undefined {
  const m = /^(der|die|das) ([A-ZÄÖÜ][a-zäöüß]+)$/.exec(item.term.trim());
  if (!m) return undefined;
  const pl = /^die ([A-ZÄÖÜ][a-zäöüß]+)$/.exec(item.plural?.trim() ?? "");
  return { gender: ({ der: "m", die: "f", das: "n" } as const)[m[1] as "der"], noun: m[2], plural: pl?.[1] };
}

export interface DeAdjSlot {
  case: DeCase;
  gender: DeGender;
  article: DeArticle;
}

/** Article + adjective for a case, gender (or plural) and article type. */
export function deAdjForm(item: VocabItem, slot: DeAdjSlot, noun?: { noun: string; plural?: string }): Generated | undefined {
  const a = deAdj(item);
  if (typeof a === "string") return undefined;
  if (slot.article === "none" && slot.case === "gen") return undefined;
  const c = CASE_INDEX[slot.case];
  const g = GENDER_INDEX[slot.gender];
  const end = ENDINGS[slot.article][c][g];
  const adj = a.stem + end;
  const art = slot.article === "none" ? "" : ARTICLES[slot.article][c][g];
  const phrase = art ? `${art} ${adj}` : adj;
  const answers = [phrase];
  // The noun may be typed too, in any common form (Hund, Hundes, Hunden).
  const word = slot.gender === "pl" ? noun?.plural : noun?.noun;
  if (word) for (const x of [word, word + "s", word + "es", word + "n", word + "en"]) answers.push(`${phrase} ${x}`);
  const where = `${CASE_NAME[slot.case]} ${GENDER_NAME[slot.gender]}`;
  const rule =
    slot.article === "der"
      ? `After der/die/das (weak endings), ${where} takes -${end}${art ? `; the article is ${art}` : ""}`
      : slot.article === "ein"
        ? `After ein/kein (mixed endings), ${where} takes -${end}${["er", "es"].includes(end) ? `: ${art} has no ending, so the adjective shows the gender` : ""}`
        : `No article (strong endings): the adjective takes the article's ending, ${where} -${end}`;
  return { answers, rule: a.rule ? `${rule}. ${a.rule}` : rule };
}

/** Warnings for a German word to look at again. */
export function deWordWarnings(item: VocabItem): string[] {
  const out: string[] = [];
  const f = item.forms ?? {};
  if (item.conj === "weak" && (f.preterite && !/te( \S+)?$/.test(f.preterite))) out.push(`forms.preterite "${f.preterite}" doesn't end in -te: is this verb strong or mixed?`);
  if (item.conj === "strong" && f.preterite && /te( \S+)?$/.test(f.preterite)) out.push(`forms.preterite "${f.preterite}" ends in -te like a weak verb: is "strong" right?`);
  if (item.conj === "strong" && f.present3 && !f.imperative && eToI(item.term.replace(/e?n$/, ""), f.present3.split(" ")[0]))
    out.push(`e → i verb without forms.imperative (gib!, lies!, nimm!): its du imperative isn't drilled`);
  return out;
}

// ---------------------------------------------------------------------------------------------
// Which forms apply to which words

export const isJaVerb = (item: VocabItem) => JA_VERB_CLASSES.includes(item.conj ?? "");
export const isJaAdj = (item: VocabItem) => JA_ADJ_CLASSES.includes(item.conj ?? "");

export function formsForClass(lang: string, item: VocabItem): readonly string[] {
  if (!item.conj) return [];
  if (lang === "ja") return isJaVerb(item) ? JA_VERB_FORMS : isJaAdj(item) ? JA_ADJ_FORMS : [];
  if (lang === "de") return item.conj === "adj" ? DE_ADJ_FORMS : ["weak", "strong", "mixed", "modal"].includes(item.conj) ? DE_VERB_FORMS : [];
  return [];
}

/** Why a word's conjugation data is wrong (for the course checker), or undefined. */
export function conjWordProblem(lang: string, item: VocabItem): string | undefined {
  if (!item.conj) return item.forms && lang === "de" ? `"forms" without "conj"` : undefined;
  if (lang === "ja") {
    if (item.forms) return `"forms" is for German; Japanese forms are generated from the dictionary form`;
    return jaWordProblem(item);
  }
  if (lang === "de") return deWordProblem(item);
  return `conjugation drills support Japanese and German (this course is "${lang}")`;
}

export function conjWordWarnings(lang: string, item: VocabItem): string[] {
  if (!item.conj) return [];
  return lang === "ja" ? jaWordWarnings(item) : lang === "de" ? deWordWarnings(item) : [];
}

// ---------------------------------------------------------------------------------------------
// Plain-English names

const JA_LABEL: Record<string, string> = {
  polite: "polite present",
  "polite-negative": "polite negative",
  "polite-past": "polite past",
  "polite-past-negative": "polite past negative",
  negative: "plain negative",
  past: "plain past",
  "past-negative": "plain past negative",
  te: "て form",
  volitional: "volitional (“let's …”)",
  potential: "potential (“can …”)",
  conditional: "conditional (〜ば, “if …”)",
  passive: "passive",
  causative: "causative (“make/let …”)",
  imperative: "imperative (command)",
  "adj-negative": "negative",
  "adj-past": "past",
  "adj-past-negative": "past negative",
  "adj-te": "て form",
  adverb: "adverb",
};
const DE_NAME: Record<string, string> = {
  present: "present",
  preterite: "Präteritum (simple past)",
  perfect: "Perfekt",
  imperative: "imperative",
  subjunctive: "Konjunktiv II",
  "adj-nom": "adjective endings: nominative",
  "adj-acc": "adjective endings: accusative",
  "adj-dat": "adjective endings: dative",
  "adj-gen": "adjective endings: genitive",
};

/** A form's name for lists and progress ("polite past", "adjectives: negative", "Perfekt"). */
export function formName(lang: string, form: string): string {
  if (lang === "ja") return form.startsWith("adj-") || form === "adverb" ? `adjectives: ${JA_LABEL[form]}` : `verbs: ${JA_LABEL[form] ?? form}`;
  return DE_NAME[form] ?? form;
}

// ---------------------------------------------------------------------------------------------
// Prompts and rounds

export interface ConjPrompt {
  item: VocabItem;
  form: string;
  /** German verbs: the person (ich … sie; imperatives du, ihr, Sie). */
  person?: string;
  /** German adjective drills: the noun and slot. */
  noun?: VocabItem;
  slot?: DeAdjSlot;
  /** The target form in plain English, e.g. "polite past negative", "Perfekt, ich". */
  label: string;
  answers: string[];
  readings?: string[];
  /** Other accepted forms worth showing after answering (not pronoun or noun variants). */
  also: string[];
  rule: string;
}

export const conjSettings = (course: Course) => course.language?.conjugation;

/** Progress key for one form: per language, like vocabulary, so it carries from A1 into A2. */
export const conjKey = (course: Course, form: string) => `${course.language?.code ?? course.id}:${form}`;

const formOpen = (course: Course, p: Progress, s: ConjugationFormSetting) => !s.lesson || !!p.lessonsDone[`${s.from ?? course.id}/${s.lesson}`];

/** The course's drilled forms with whether each is unlocked. */
export function conjForms(course: Course, p: Progress): { setting: ConjugationFormSetting; open: boolean }[] {
  const lang = course.language?.code ?? "";
  const usable = new Set([...(lang === "ja" ? [...JA_VERB_FORMS, ...JA_ADJ_FORMS] : lang === "de" ? [...DE_VERB_FORMS, ...DE_ADJ_FORMS] : [])]);
  return (conjSettings(course)?.forms ?? []).filter((s) => usable.has(s.form as never)).map((setting) => ({ setting, open: formOpen(course, p, setting) }));
}

/** Words in the course that can be conjugated at all (whatever is unlocked). */
export function conjWords(course: Course): VocabItem[] {
  const lang = course.language?.code ?? "";
  return (course.vocab ?? []).filter((v) => formsForClass(lang, v).length && !conjWordProblem(lang, v));
}

/** Every prompt for one word and form (all persons, all adjective slots). */
export function promptsFor(course: Course, item: VocabItem, form: string, nouns: VocabItem[] = [], rand = Math.random): ConjPrompt[] {
  const lang = course.language?.code ?? "";
  if (!formsForClass(lang, item).includes(form)) return [];
  if (lang === "ja") {
    const g = jaForm(item, form);
    return g ? [{ item, form, label: JA_LABEL[form], answers: g.answers, readings: g.readings, also: [...new Set(g.answers.slice(1))], rule: g.rule }] : [];
  }
  if (item.conj === "adj") {
    const c = form.slice(4) as DeCase;
    const out: ConjPrompt[] = [];
    const pick = <T,>(xs: T[]) => xs[Math.floor(rand() * xs.length)];
    const parsed = nouns.flatMap((n) => {
      const d = deNoun(n);
      return d ? [{ n, d }] : [];
    });
    for (const gender of ["m", "f", "n", "pl"] as DeGender[])
      for (const article of ["der", "ein", "none"] as DeArticle[]) {
        const fits = parsed.filter(({ d }) => (gender === "pl" ? !!d.plural : d.gender === gender));
        if (!fits.length) continue;
        const { n: noun, d } = pick(fits);
        const slot = { case: c, gender, article };
        const g = deAdjForm(item, slot, d);
        if (!g) continue;
        const art = article === "none" ? "no article" : article === "der" ? `with ${gender === "pl" ? "die" : "der/die/das"}` : `with ${gender === "pl" ? "kein" : "ein"}`;
        out.push({ item, form, noun, slot, label: `${CASE_NAME[c]} ${gender === "pl" ? "plural" : "singular"}, ${art}`, answers: g.answers, also: [], rule: g.rule });
      }
    return out;
  }
  const persons = form === "imperative" ? DE_IMPERATIVES : DE_PERSONS;
  const out: ConjPrompt[] = [];
  for (const person of persons) {
    const g = deVerbForm(item, form, person);
    if (!g) continue;
    const who = PERSON_LABEL[person];
    const label =
      form === "present" ? `${who}, present` : form === "preterite" ? `Präteritum, ${who}` : form === "perfect" ? `Perfekt, ${who}` : form === "imperative" ? `imperative, ${who}` : `Konjunktiv II, ${who}`;
    out.push({ item, form, person, label, answers: g.answers, also: g.answers.slice(1).filter((a) => !/^(ich|du|er|sie|es|wir|ihr) /i.test(a)), rule: g.rule });
  }
  return out;
}

export type { ConjTally };

export function tallyOf(p: Progress, key: string): ConjTally {
  return p.conj?.[key] ?? { right: 0, wrong: 0 };
}

/** Record one counted answer for a form. */
export function recordConj(p: Progress, key: string, correct: boolean, now = today()): Progress {
  const t = tallyOf(p, key);
  return { ...p, conj: { ...p.conj, [key]: { right: t.right + (correct ? 1 : 0), wrong: t.wrong + (correct ? 0 : 1), last: now } } };
}

export const DEFAULT_ROUND = 10;

/**
 * One round: prompts for unlocked words × unlocked forms. Forms the learner gets wrong more
 * often come up more; no word-and-form pair repeats while others are left.
 */
export function buildRound(course: Course, p: Progress, n = conjSettings(course)?.round ?? DEFAULT_ROUND, rand = Math.random, now = today()): ConjPrompt[] {
  const lang = course.language?.code ?? "";
  const forms = conjForms(course, p).filter((f) => f.open).map((f) => f.setting.form);
  if (!forms.length) return [];
  const unlocked = unlockedItems(course, p, now);
  const words = unlocked.filter((v) => formsForClass(lang, v).length && !conjWordProblem(lang, v));
  const nouns = lang === "de" ? unlocked.filter((v) => deNoun(v)) : [];
  const pairs: { item: VocabItem; form: string; w: number }[] = [];
  for (const item of words)
    for (const form of forms) {
      if (!formsForClass(lang, item).includes(form)) continue;
      if (!promptsFor(course, item, form, nouns, rand).length) continue;
      const t = tallyOf(p, conjKey(course, form));
      const acc = t.right + t.wrong ? t.right / (t.right + t.wrong) : 0.5;
      pairs.push({ item, form, w: 1.5 - acc });
    }
  const out: ConjPrompt[] = [];
  let pool = shuffled(pairs);
  while (out.length < n && pairs.length) {
    if (!pool.length) pool = shuffled(pairs);
    // Avoid the same word twice in a row, unless every pair left is for that word.
    const prev = out[out.length - 1];
    const other = pool.filter((x) => !prev || x.item.id !== prev.item.id);
    const cands = other.length ? other : pool;
    const total = cands.reduce((s, x) => s + x.w, 0);
    let r = rand() * total;
    let k = 0;
    while (k < cands.length - 1 && r >= cands[k].w) r -= cands[k++].w;
    const pair = cands[k];
    pool.splice(pool.indexOf(pair), 1);
    const variants = promptsFor(course, pair.item, pair.form, nouns, rand);
    out.push(variants[Math.floor(rand() * variants.length)]);
  }
  return out;
}

/** Check a typed answer: the same leniencies as vocabulary recall. */
export function checkConj(prompt: ConjPrompt, typed: string, lang = "de"): Verdict {
  const [first, ...rest] = prompt.answers;
  if (lang === "ja") {
    const item: VocabItem = {
      id: prompt.item.id,
      lesson: prompt.item.lesson,
      term: first,
      reading: prompt.readings?.[0],
      alt: [...rest, ...(prompt.readings?.slice(1) ?? [])],
      meanings: prompt.item.meanings,
    };
    return checkRecallJa(item, typed);
  }
  const item: VocabItem = { id: prompt.item.id, lesson: prompt.item.lesson, term: first, alt: rest, meanings: prompt.item.meanings, pos: "phrase" };
  return checkRecall(item, typed, lang);
}

/** Per-form accuracy for the Vocabulary tab: every drilled form, unlocked or not. */
export function conjSummary(course: Course, p: Progress) {
  const lang = course.language?.code ?? "";
  return conjForms(course, p).map(({ setting, open }) => {
    const t = tallyOf(p, conjKey(course, setting.form));
    return { form: setting.form, name: formName(lang, setting.form), lesson: setting.lesson, from: setting.from, open, ...t };
  });
}
